export const title = "How to Set Up a Document Scanning Station You Can Pack Away";
export const metaTitle = "How to Set Up a Pack-Away Scanning Station";
export const metaDescription = "Plan a compact scanning workflow with supported paper paths, review space, file checks, and an orderly pack-away routine.";
export const author = "Jamie Cole, Lead Product Researcher";
